import { Injectable, ConflictException, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { CreateUserDto } from './dto/create-user.dto';
import { UpdateUserDto } from './dto/update-user.dto';
import { Role } from '@prisma/client';
import * as bcrypt from 'bcryptjs';
import { validateCpf } from '../../common/utils/cpf.util';

@Injectable\(\)
export class UsersService {
  constructor\(private prisma: PrismaService\) {}

  async create\(dto: CreateUserDto\) {
    const cleanCpf = dto.cpf.replace\(/\\D/g, ''\);
    if \(!validateCpf\(cleanCpf\)\) throw new ConflictException\('CPF inválido'\);

    const existing = await this.prisma.user.findFirst\({
      where: { OR: [{ cpf: cleanCpf }, { email: dto.email.toLowerCase\(\) }] },
    }\);
    if \(existing\) throw new ConflictException\('CPF ou e-mail já cadastrado'\);

    const passwordHash = await bcrypt.hash\(dto.password, 10\);

    const user = await this.prisma.user.create\({
      data: {
        name: dto.name,
        cpf: cleanCpf,
        email: dto.email.toLowerCase\(\),
        passwordHash,
        birthdate: dto.birthdate ? new Date\(dto.birthdate\) : undefined,
        phone: dto.phone,
      },
    }\);

    const { passwordHash: _, ...result } = user;
    return result;
  }

  async findAll\(search?: string, page = 1, limit = 20\) {
    const skip = \(page - 1\) * limit;
    const where = search
      ? {
          OR: [
            { name: { contains: search, mode: 'insensitive' as const } },
            { cpf: { contains: search.replace\(/\\D/g, ''\) } },
            { email: { contains: search, mode: 'insensitive' as const } },
          ],
        }
      : {};

    const [data, total] = await Promise.all\([
      this.prisma.user.findMany\({
        where,
        skip,
        take: limit,
        orderBy: { name: 'asc' },
        select: {
          id: true,
          name: true,
          cpf: true,
          email: true,
          role: true,
          birthdate: true,
          phone: true,
          isActive: true,
          createdAt: true,
        },
      }\),
      this.prisma.user.count\({ where }\),
    ]\);

    return { data, total, page, limit };
  }

  async findOne\(id: string\) {
    const user = await this.prisma.user.findUnique\({
      where: { id },
      select: {
        id: true,
        name: true,
        cpf: true,
        email: true,
        role: true,
        birthdate: true,
        phone: true,
        avatarUrl: true,
        isActive: true,
        createdAt: true,
        appointments: {
          take: 5,
          orderBy: { scheduledAt: 'desc' },
          include: { service: true, professional: true },
        },
      },
    }\);
    if \(!user\) throw new NotFoundException\('Usuário não encontrado'\);
    return user;
  }

  async update\(id: string, dto: UpdateUserDto\) {
    const user = await this.prisma.user.findUnique\({ where: { id } }\);
    if \(!user\) throw new NotFoundException\('Usuário não encontrado'\);

    const data: any = { ...dto };
    if \(dto.password\) {
      data.passwordHash = await bcrypt.hash\(dto.password, 10\);
      delete data.password;
    }
    if \(dto.birthdate\) data.birthdate = new Date\(dto.birthdate\);

    const updated = await this.prisma.user.update\({ where: { id }, data }\);
    const { passwordHash, ...result } = updated;
    return result;
  }

  async remove\(id: string\) {
    await this.prisma.user.update\({ where: { id }, data: { isActive: false } }\);
    return { message: 'Usuário desativado' };
  }
}
